 const string Folder="Assets/Recoil3D/RoadCheckpoint",Marker="Curved forecourt approach and abandoned military checkpoint";
 static Material road,soil,stone,olive,canvas,black,steel,rust,glass,paper,cloth;static int serial;
 static T[] All<T>(Scene s)where T:Component{return s.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<T>(true)).ToArray();}
 static Transform G(Transform p,string n,Vector3 at){var t=new GameObject(n).transform;t.SetParent(p,false);t.position=at;return t;}
 static Transform B(Transform p,string n,Vector3 at,Vector3 size,Material m,PrimitiveType type=PrimitiveType.Cube){var t=GameObject.CreatePrimitive(type).transform;t.name=n;t.SetParent(p,false);t.position=at;t.localScale=size;Object.DestroyImmediate(t.GetComponent<Collider>());t.GetComponent<Renderer>().sharedMaterial=m;return t;}
 static Transform Rod(Transform p,string n,Vector3 a,Vector3 b,float radius,Material m){var t=B(p,n,(a+b)*.5f,new Vector3(radius*2,(a-b).magnitude*.5f,radius*2),m,PrimitiveType.Cylinder);t.rotation=Quaternion.FromToRotation(Vector3.up,b-a);return t;}
 static Material Mat(string n,Color c){string path=Folder+"/"+n+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m){m=new Material(Shader.Find("Recoil/3D/Weathered Surface"));AssetDatabase.CreateAsset(m,path);}m.color=c;m.enableInstancing=true;m.SetFloat("_Glossiness",.06f);m.SetFloat("_Weathering",.8f);EditorUtility.SetDirty(m);return m;}
 static Mesh Save(string name,Mesh mesh){string path=Folder+"/"+name+".asset";var old=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(old){EditorUtility.CopySerialized(mesh,old);Object.DestroyImmediate(mesh);return old;}mesh.name=name;AssetDatabase.CreateAsset(mesh,path);return mesh;}
 static Transform Poly(Transform p,string name,Vector3[] outline,Material m){var t=G(p,name,Vector3.zero);var vs=new List<Vector3>();vs.Add(outline.Aggregate(Vector3.zero,(a,b)=>a+b)/outline.Length);vs.AddRange(outline);var tris=new List<int>();for(int i=0;i<outline.Length;i++){int b=i+1,c=(i+1)%outline.Length+1;if(Vector3.Cross(vs[b]-vs[0],vs[c]-vs[0]).y>0)tris.AddRange(new[]{0,b,c});else tris.AddRange(new[]{0,c,b});}var mesh=new Mesh();mesh.SetVertices(vs);mesh.SetTriangles(tris,0);mesh.RecalculateNormals();mesh.RecalculateBounds();t.gameObject.AddComponent<MeshFilter>().sharedMesh=Save(name,mesh);t.gameObject.AddComponent<MeshRenderer>().sharedMaterial=m;return t;}
 static void Approach(Transform p){var g=G(p,"Flared worn driveway joining main road",Vector3.zero);float[] x={-84.2f,-82.6f,-80.1f,-76,-69,-63,-57,-53};float[] z={11,8,6,4.6f,4.7f,6.8f,10,11};var pts=new List<Vector3>();for(int i=0;i<x.Length;i++)pts.Add(new Vector3(x[i],.013f,-z[i]));for(int i=x.Length-1;i>=0;i--)pts.Add(new Vector3(i==0?-84.45f:x[i],.013f,z[i]));Poly(g,"Curving widened entrance asphalt",pts.ToArray(),road);
  // Broken soil shoulders and discontinuous kerbs follow the curved margins, leaving the mouth open.
  var rng=new System.Random(711);foreach(int side in new[]{-1,1})for(int i=0;i<x.Length-1;i++){var a=new Vector3(x[i],0,side*z[i]);var b=new Vector3(x[i+1],0,side*z[i+1]);var strip=new[]{a+Vector3.up*.005f,b+Vector3.up*.005f,b+new Vector3(0,.005f,side*1.0f),a+new Vector3(0,.005f,side*1.0f)};Poly(g,"Gravel shoulder "+side+"-"+i,strip,soil);int n=Mathf.CeilToInt((a-b).magnitude/1.2f);for(int j=0;j<n;j++){if((i+j)%4==0)continue;var pos=Vector3.Lerp(a,b,(j+.5f)/n);pos.y=.045f;var curb=B(g,"Broken curved entry kerb",pos,new Vector3(.18f,.09f,.86f),stone);curb.rotation=Quaternion.LookRotation(b-a);}}
  for(int i=0;i<24;i++){var at=new Vector3(-83+(float)rng.NextDouble()*18,.023f,((float)rng.NextDouble()-.5f)*8);float r=.22f+(float)rng.NextDouble()*.6f;var points=Enumerable.Range(0,7).Select(j=>at+new Vector3(Mathf.Cos(j*Mathf.PI*2/7)*r*(.75f+(float)rng.NextDouble()*.4f),0,Mathf.Sin(j*Mathf.PI*2/7)*r*.55f)).ToArray();Poly(g,"Old irregular tar repair "+i,points,i%3==0?soil:black);}
  for(int side=0;side<2;side++)for(int i=0;i<12;i++){var a=new Vector3(-77+i*.72f,.027f,2.0f+side*.45f+Mathf.Sin(i*.18f)*.5f);Rod(g,"Old braking and turning tyre scrape",a,a+new Vector3(.55f,0,.05f),.014f,black);}
 }
 static void Truck(Transform p){var g=G(p,"Abandoned government army cargo truck - burned checkpoint wreck",new Vector3(-73,0,8.2f));
  B(g,"Heavy ladder chassis",new Vector3(-73,.58f,8.2f),new Vector3(6.7f,.30f,2.1f),steel);B(g,"Military cargo bed",new Vector3(-74.25f,1.04f,8.2f),new Vector3(4.0f,.18f,2.45f),olive);foreach(float z in new[]{6.98f,9.42f})B(g,"Cargo side board",new Vector3(-74.25f,1.35f,z),new Vector3(4.0f,.52f,.08f),olive);
  B(g,"Square old army cab",new Vector3(-71.25f,1.61f,8.2f),new Vector3(1.75f,1.8f,2.36f),olive);B(g,"Long engine bonnet",new Vector3(-69.95f,1.27f,8.2f),new Vector3(1.0f,.75f,2.12f),olive);B(g,"Blackened cab side window",new Vector3(-71.15f,2.02f,6.99f),new Vector3(1.22f,.62f,.035f),black);B(g,"Broken windscreen",new Vector3(-70.35f,2.02f,8.2f),new Vector3(.035f,.65f,2.0f),black);B(g,"Army cab roof",new Vector3(-71.25f,2.55f,8.2f),new Vector3(1.9f,.12f,2.48f),olive);
  B(g,"Heavy front bumper",new Vector3(-69.35f,.71f,8.2f),new Vector3(.16f,.20f,2.6f),steel);for(int i=0;i<8;i++)B(g,"Radiator grille slat",new Vector3(-69.40f,1.22f,7.55f+i*.18f),new Vector3(.04f,.47f,.05f),black);foreach(float z in new[]{7.38f,9.02f})B(g,"Broken headlamp",new Vector3(-69.38f,1.28f,z),new Vector3(.05f,.24f,.24f),glass,PrimitiveType.Cylinder);
  foreach(float x in new[]{-75.4f,-73.85f,-70.65f})foreach(float z in new[]{6.94f,9.46f}){var t=B(g,"Heavy partly deflated truck tyre",new Vector3(x,.46f,z),new Vector3(.92f,.20f,.92f),black,PrimitiveType.Cylinder);t.rotation=Quaternion.Euler(90,0,0);var hub=B(g,"Rusted truck wheel hub",new Vector3(x,.46f,z+(z<8?-.20f:.20f)),new Vector3(.45f,.025f,.45f),rust,PrimitiveType.Cylinder);hub.rotation=t.rotation;}
  // Sagging canvas with a missing lower panel, revealing the empty load bed.
  var verts=new List<Vector3>();var tris=new List<int>();for(int end=0;end<2;end++)for(int i=0;i<7;i++){float a=i*Mathf.PI/6;verts.Add(new Vector3(end==0?-76.25f:-72.25f,1.8f+Mathf.Sin(a)*1.0f,8.2f+Mathf.Cos(a)*1.23f));}for(int i=0;i<6;i++)tris.AddRange(new[]{i,i+7,i+1,i+1,i+7,i+8});var mesh=new Mesh();mesh.SetVertices(verts);mesh.SetTriangles(tris,0);mesh.RecalculateNormals();mesh.RecalculateBounds();var tarp=G(g,"Sagging old cargo canvas",Vector3.zero);tarp.gameObject.AddComponent<MeshFilter>().sharedMesh=Save("Sagging military cargo canvas",mesh);tarp.gameObject.AddComponent<MeshRenderer>().sharedMaterial=canvas;
  for(int i=0;i<7;i++){B(g,"Burn scar on cab and cargo skin",new Vector3(-75.7f+i*.83f,1.45f,6.91f),new Vector3(.38f,.55f,.025f),black);B(g,"Chipped army paint and corrosion",new Vector3(-75.5f+i*.8f,1.18f,6.88f),new Vector3(.24f,.13f,.012f),rust);}var door=B(g,"Bent cab door hanging open",new Vector3(-71.7f,1.55f,6.4f),new Vector3(1.15f,1.45f,.075f),olive);door.rotation=Quaternion.Euler(0,43,-7);B(g,"Open door empty window",new Vector3(-71.7f,1.97f,6.35f),new Vector3(.80f,.51f,.026f),black).rotation=door.rotation;
 }
 static void GuardRemains(Transform p){var g=G(p,"Abandoned field vehicle inspection post",Vector3.zero);B(g,"Folded field table top",new Vector3(-70.1f,.77f,3.9f),new Vector3(1.8f,.07f,.80f),olive);foreach(float x in new[]{-70.8f,-69.4f})foreach(float side in new[]{-1f,1f})Rod(g,"Crossed folding table leg",new Vector3(x,.05f,3.9f+side*.4f),new Vector3(x,.75f,3.9f-side*.3f),.022f,steel);B(g,"Dead field radio",new Vector3(-70.35f,.99f,3.9f),new Vector3(.5f,.38f,.32f),olive);Rod(g,"Bent radio aerial",new Vector3(-70.51f,1.12f,3.9f),new Vector3(-70.75f,1.9f,3.9f),.009f,steel);for(int i=0;i<4;i++)B(g,"Old checkpoint documents on table",new Vector3(-69.9f+i*.11f,.817f+i*.003f,3.8f+i*.04f),new Vector3(.21f,.003f,.29f),paper).rotation=Quaternion.Euler(0,i*29,0);
  B(g,"Open metal stores case",new Vector3(-72.5f,.22f,3.3f),new Vector3(.85f,.44f,.60f),olive);B(g,"Stores case lid fallen open",new Vector3(-73.1f,.08f,3.3f),new Vector3(.75f,.08f,.57f),olive).rotation=Quaternion.Euler(0,-18,0);
  var brazier=B(g,"Cold rusted sentry warming drum",new Vector3(-68.7f,.42f,6),new Vector3(.62f,.84f,.62f),rust,PrimitiveType.Cylinder);B(g,"Cold charcoal in old drum",new Vector3(-68.7f,.85f,6),new Vector3(.51f,.02f,.51f),black,PrimitiveType.Cylinder);
  var rng=new System.Random(1978);for(int i=0;i<65;i++){float x=-77+(float)rng.NextDouble()*10,z=(i%2==0?-1:1)*(2.2f+(float)rng.NextDouble()*8);var at=new Vector3(x,.035f,z);if(i%7==0){B(g,"Discarded old helmet",at+Vector3.up*.10f,new Vector3(.30f,.20f,.29f),olive,PrimitiveType.Sphere);continue;}if(i%9==0){var sh=B(g,"Cracked discarded riot shield",at+Vector3.up*.04f,new Vector3(.48f,.07f,.78f),black);sh.rotation=Quaternion.Euler(0,i*37,-8);continue;}if(i%4==0){B(g,"Lost boot or torn uniform fragment",at+Vector3.up*.035f,new Vector3(.22f,.07f,.33f),cloth).rotation=Quaternion.Euler(0,i*51,6);continue;}var piece=B(g,i%3==0?"Old stone and shattered paving":"Broken dark glass and scattered hardware",at,new Vector3(.05f+(float)rng.NextDouble()*.16f,.02f,.04f+(float)rng.NextDouble()*.13f),i%3==0?stone:steel);piece.rotation=Quaternion.Euler(0,i*27,0);}
 }
 static void Batch(Transform root){foreach(var group in root.GetComponentsInChildren<MeshFilter>().GroupBy(f=>f.GetComponent<MeshRenderer>().sharedMaterial).ToArray()){var mesh=new Mesh{indexFormat=IndexFormat.UInt32};mesh.CombineMeshes(group.Select(f=>new CombineInstance{mesh=f.sharedMesh,transform=root.worldToLocalMatrix*f.transform.localToWorldMatrix}).ToArray(),true,true);var t=G(root,"Static checkpoint detail - "+group.Key.name,Vector3.zero);t.gameObject.AddComponent<MeshFilter>().sharedMesh=Save("Checkpoint batch "+serial++,mesh);t.gameObject.AddComponent<MeshRenderer>().sharedMaterial=group.Key;foreach(var f in group){Object.DestroyImmediate(f.GetComponent<MeshRenderer>());Object.DestroyImmediate(f);}}}
 static string VertexKey(Vector3 p){return Mathf.RoundToInt(p.x*1000)+","+Mathf.RoundToInt(p.y*1000)+","+Mathf.RoundToInt(p.z*1000);}
 static string TriangleKey(Vector3 a,Vector3 b,Vector3 c){var keys=new[]{VertexKey(a),VertexKey(b),VertexKey(c)};Array.Sort(keys,StringComparer.Ordinal);return string.Join(";",keys);}
 public static string MakeArmyTruckEditable(){
  if(EditorApplication.isPlayingOrWillChangePlaymode)throw new Exception("Stop Play first");var s=SceneManager.GetSceneByPath("Assets/Scenes/3D/RecoilPrototype.unity");var w=All<RecoilPrototype>(s).Single();var root=w.transform.Find(Marker);if(root.Find("Army truck - single editable object"))return "Already a single object";
  EditorSceneManager.SaveScene(s,"Backups/RoadCheckpoint/BeforeSingleTruck-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".unity",true);
  olive=AssetDatabase.LoadAssetAtPath<Material>(Folder+"/Faded government military olive.mat");canvas=AssetDatabase.LoadAssetAtPath<Material>(Folder+"/Old scorched military canvas.mat");black=AssetDatabase.LoadAssetAtPath<Material>(Folder+"/Burned rubber soot and cold recesses.mat");steel=AssetDatabase.LoadAssetAtPath<Material>(Folder+"/Dull checkpoint hardware.mat");rust=AssetDatabase.LoadAssetAtPath<Material>(Folder+"/Abandoned military vehicle rust.mat");glass=AssetDatabase.LoadAssetAtPath<Material>(Folder+"/Unlit broken army vehicle glass.mat");
  var legacy=root.Find("Abandoned government army cargo truck - burned checkpoint wreck");if(!legacy)throw new Exception("Truck reference missing");legacy.name="Legacy empty army truck reference";Truck(root);var truck=root.Find("Abandoned government army cargo truck - burned checkpoint wreck");var keys=new HashSet<string>();int expected=0;
  foreach(var f in truck.GetComponentsInChildren<MeshFilter>()){var v=f.sharedMesh.vertices;var triangles=f.sharedMesh.triangles;for(int i=0;i<triangles.Length;i+=3){keys.Add(TriangleKey(f.transform.TransformPoint(v[triangles[i]]),f.transform.TransformPoint(v[triangles[i+1]]),f.transform.TransformPoint(v[triangles[i+2]])));expected++;}}
  var plans=new List<KeyValuePair<MeshFilter,Mesh>>();int removed=0;foreach(var f in root.GetComponentsInChildren<MeshFilter>().Where(f=>f.name.StartsWith("Static checkpoint detail - "))){var source=f.sharedMesh;var vertices=source.vertices;var triangles=source.triangles;var keep=new List<int>();int count=0;for(int i=0;i<triangles.Length;i+=3){if(keys.Contains(TriangleKey(f.transform.TransformPoint(vertices[triangles[i]]),f.transform.TransformPoint(vertices[triangles[i+1]]),f.transform.TransformPoint(vertices[triangles[i+2]]))))count++;else keep.AddRange(new[]{triangles[i],triangles[i+1],triangles[i+2]});}if(count==0)continue;removed+=count;var mesh=Object.Instantiate(source);mesh.SetTriangles(keep,0);mesh.RecalculateBounds();plans.Add(new KeyValuePair<MeshFilter,Mesh>(f,mesh));}
  if(removed<expected*.97f||removed>expected*1.03f)throw new Exception("Truck extraction mismatch "+removed+" / "+expected);int n=0;foreach(var plan in plans)plan.Key.sharedMesh=Save("Checkpoint without truck "+n++,plan.Value);
  ForecourtEditableCarsPass.MakeSingle(truck);truck.name="Army truck - single editable object";Object.DestroyImmediate(legacy.gameObject);if(truck.childCount!=0||truck.GetComponentsInChildren<MeshRenderer>().Length!=1)throw new Exception("Truck still has parts");AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);return "PASS single editable army truck, one mesh/renderer, no child parts; "+removed+" original truck triangles removed from checkpoint batches, other scenery retained.";
 }
 public static string Apply(){if(EditorApplication.isPlayingOrWillChangePlaymode)throw new Exception("Stop Play first");var s=SceneManager.GetSceneByPath("Assets/Scenes/3D/RecoilPrototype.unity");if(!s.isLoaded)throw new Exception("Open outdoor first");var w=All<RecoilPrototype>(s).Single();if(w.transform.Find(Marker))return "Already applied";Directory.CreateDirectory(Folder);AssetDatabase.Refresh();serial=0;string backup="Backups/RoadCheckpoint/"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".unity";Directory.CreateDirectory(Path.GetDirectoryName(backup));EditorSceneManager.SaveScene(s,backup,true);
  road=Mat("Blended aged entrance asphalt",new Color(.105f,.12f,.115f));soil=Mat("Dirty gravel road shoulder",new Color(.15f,.15f,.12f));stone=Mat("Broken entry kerb and rubble",new Color(.25f,.25f,.21f));olive=Mat("Faded government military olive",new Color(.16f,.18f,.12f));canvas=Mat("Old scorched military canvas",new Color(.115f,.13f,.09f));black=Mat("Burned rubber soot and cold recesses",new Color(.025f,.032f,.03f));steel=Mat("Dull checkpoint hardware",new Color(.16f,.17f,.15f));rust=Mat("Abandoned military vehicle rust",new Color(.22f,.115f,.065f));glass=Mat("Unlit broken army vehicle glass",new Color(.055f,.075f,.07f));paper=Mat("Weathered old check papers",new Color(.28f,.27f,.21f));cloth=Mat("Rotten uniform fragments",new Color(.10f,.12f,.08f));
  var before=All<Collider2D>(s).Select(c=>c.GetInstanceID()+"|"+c.bounds).ToArray();var root=G(w.transform,Marker,Vector3.zero);Approach(root);Truck(root);GuardRemains(root);
  var legacy=w.transform.Find("Opening approach expanded 20m - editable");legacy.Find("Road from main road into forecourt").GetComponent<Renderer>().enabled=false;legacy.Find("New approach ground extension").GetComponent<Renderer>().enabled=false;foreach(var t in legacy.Cast<Transform>().Where(t=>t.name=="Broken access road kerb")){var r=t.GetComponent<Renderer>();if(r)r.enabled=false;}
  Batch(root);if(root.GetComponentsInChildren<Collider>(true).Length+root.GetComponentsInChildren<Collider2D>(true).Length>0)throw new Exception("New unintended blockers");if(!before.SequenceEqual(All<Collider2D>(s).Select(c=>c.GetInstanceID()+"|"+c.bounds)))throw new Exception("Collision changed");AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);Directory.CreateDirectory("output/road-checkpoint");string report="PASS flared curved forecourt driveway, broken edge kerbs, gravel shoulders, old patches and tyre traces; abandoned army truck and field inspection remains on left of roadblock;65 irregular old debris pieces; no new lights or collision. Backup: "+backup;File.WriteAllText("output/road-checkpoint/verification.txt",report);File.WriteAllText("output/road-checkpoint/references.txt","Road forecourt composition reference: https://www.johnnovis.com/saltdean (1972 Caffyns Garage).\nPrimary photograph,1982 road check,Chris Niedenthal / DSH: https://galeriarzeczna.pl/wystawa/niedenthal/\nIPN road checks and street closures: https://archiwum.ipn.gov.pl/pl/aktualnosci/63268,Stan-wojenny-w-dokumentach-i-na-zdjeciach-z-zasobu-Archiwum-IPN.html\nThe curved driveway, military cargo wreck, radio table, cold sentry drum and aged conflict debris are fictional scene design, not a claim that all objects occur in one historical photograph.\n");return report;
 }
